-- ============================================================================
-- عنقود التأشيرات: 19 صفحة ← 8، وقاعدة إسناد تُطبَّق (2026-08-06)
-- ============================================================================
-- عمودان قِيسا فوجدا مختلفين فعلاً، فبقيا:
--   • turkey-visa-types-2026 (1,085 قراءة) — كم تكلّف التأشيرة بحسب الجنسية.
--   • syria-turkey-visa-types-2026 (245)   — الأنواع السبعة المتاحة للسوريين.
-- تداخلهما دون 18%، وكلٌّ يجيب سؤالاً لا يجيبه الآخر. وقد كانا لا يتقاطعان
-- برابط واحد، فأُضيف لكلٍّ منهما رابط إلى الآخر.
--
-- أمّا ما تحتهما فلا. خمس من صفحات الأنواع السبع بين 130 و190 كلمة وتتداخل
-- فيما بينها 18-39%، والصفحة الأمّ تجمع السبعة في جدول مقارنة واحد. وأربع
-- صفحات من كانون الأول 2025 تعيد سؤال «أي تأشيرة أحتاج / هل تكفي الإلكترونية
-- / من يُعفى» وهو ما يجيبه عمود الأسعار جنسيةً جنسية. وصفحة تأشيرة العلاج
-- (180 كلمة) تكرّر صفحة الفيزا الطبية (508 كلمات، مصدرها mfa.gov.tr).
--
-- ── لماذا كان هذا العنقود أهمّ من حجمه ──────────────────────────────────
--
-- CLAUDE.md صريح: انسب المحتوى لمصدره الأوّلي، ولا تنسبه لصفحة تواصل
-- اجتماعي. وثماني صفحات هنا تسنِد رسومها إلى منشور على فيسبوك لاتحاد أهلي
-- (UCSO): 125 دولاراً للعبور، و145 للدراسة، و165 للنقل البري.
--
-- والرسم القانوني التركي للتأشيرة نفسها — تحقّقنا منه من جدول رئاسة إدارة
-- الهجرة نفسها (goc.gov.tr)، نافذاً من 1 كانون الثاني 2026 بموجب الجريدة
-- الرسمية 31 كانون الأول 2025 العدد 33124 — هو 9,376.40 ليرة، أي نحو 234
-- دولاراً بأسعار اليوم. الفرق ليس هامشياً، والموقع كان ينشر الرقمين معاً بلا
-- إشارة إلى أنّهما يختلفان، ولا إلى أنّ أحدهما مأخوذ من فيسبوك.
--
-- والعلاج ليس حذف الأرقام بالدولار: من يقدّم عبر المكتب المعتمد داخل سوريا
-- يحتاج فعلاً أن يعرف ما يتقاضاه ذلك المكتب، وإعلان الاتحاد هو الرواية
-- الوحيدة المتاحة عنه. العلاج أن نقول ذلك بالضبط — مَن أعلنه، وأنّه ليس
-- منشوراً حكومياً تركياً، وما هو الرسم القانوني، ورابط الصفحة التي تحمله.
--
-- وأثناء التحقّق راجعنا جدول عمود الأسعار كلّه على goc.gov.tr: كل رقم فيه
-- مطابق — 9,376.40 و31,410.00 و18,813.80 و15,672.10. لم يحتج تصحيحاً.
--
-- شغّله بعد اكتمال نشر الشيفرة (التحويلات في next.config.ts).
-- ============================================================================

-- syria-turkey-visa-types-2026  ←  6 صفحة
UPDATE articles SET
    documents = ARRAY['جواز سفر ساري ٦ أشهر (أو سنة للنقل البري) مع صفحتين فارغتين', 'صور بيومترية ٤٠×٥٥ مم بخلفية بيضاء (آخر ٦ أشهر)', 'استمارة طلب التأشيرة موقّعة', 'حجز فندقي + تذاكر طيران', 'شهادة سجلّ جنائي (فوق ١٨ فقط) مترجمة للتركية', 'كشف حساب بنكي أصلي مختوم وموقّع', 'بيان عمل من جهة العمل (الاسم، الجواز، المسمّى الوظيفي، الراتب)', 'وثائق خاصّة بنوع التأشيرة (دعوة، قبول جامعي، USHAŞ/HİB...)', 'موافقة كاتب العدل لأطفال دون ١٢ في حال عدم سفر الوالدين معاً', 'للتأشيرة التجارية: خطاب دعوة رسمي موثّق من كاتب العدل', 'للتأشيرة التجارية: وثائق الشركة الداعية — غرفة التجارة والسجل التجاري والبيان الضريبي', 'لتأشيرة البحّارة: عقد بحري ساري ووثائق السفينة وشهادات بحرية مناسبة', 'إن كنت تقدّم من خارج سوريا: إثبات إقامة قانونية في بلد التقديم (إقامة أو فيزا أو ختم دخول)']::text[],
    steps = ARRAY['1️⃣ اختر نوع التأشيرة المناسب — راجع الأنواع السبعة في المقال وحدّد التي تطابق غرض سفرك (سياحة عابرة، اجتماع، تجارة، دراسة، علاج، نقل، بحارة).', '2️⃣ جهّز جواز السفر والصور — تأكّد أنّ جوازك ساري ٦ أشهر (أو سنة للنقل) ولديه صفحتين فارغتين. التقط صور بيومترية حديثة (٤٠×٥٥ مم، خلفية بيضاء).', '3️⃣ جهّز الوثائق الخاصّة بنوعك — كلّ تأشيرة لها متطلّبات إضافية: دعوة للأعمال، قبول جامعي للدراسة، USHAŞ/HİB للعلاج، إلخ. لا تنقص أيّ وثيقة.', '4️⃣ ترجم الوثائق للتركية مع مترجم محلّف — الترجمات بالتركية فقط مقبولة، ومن مترجم محلّف (Yeminli Tercüman) معتمد. لا تستعمل ترجمات غير رسمية.', '5️⃣ احجز موعدك على Visa FG — الموقع الرسمي الوحيد المعتمد في سوريا: sy.visafg.com/ar — احجز موعدك ولا تدفع لأيّ سمسار.', '6️⃣ قدّم الطلب شخصياً وادفع الرسم — احضر في موعدك مع كلّ الأوراق. الأطفال فوق ١٢ يجب أن يحضروا. ادفع الرسم بالدولار حسب نوع التأشيرة.', '7️⃣ تابع طلبك إلكترونياً — لا تتّصل بأيّ سمسار يدّعي القدرة على تسريع طلبك. كلّ المتابعة عبر sy.visafg.com فقط.']::text[],
    tips = ARRAY['احفظ رابط Visa FG (sy.visafg.com/ar) كمصدر وحيد رسمي — أيّ موقع آخر يدّعي تقديم الخدمة هو احتيال', 'لا تدفع رشاوى لأيّ سمسار — UCSO أعلنت رسمياً أنّ ذلك احتيال', 'الأطفال دون ١٢ لا يحتاجون الحضور — موافقة كاتب عدل من الوالد غير المسافر تكفي', 'كلّ الوثائق يجب أن تكون أصلية ومختومة وموقّعة — النسخ غير المختومة تُرفض', 'الترجمة المحلّفة بالتركية فقط — لا ترجمات إنجليزية أو غير رسمية', 'تأشيرة العلاج تتطلّب وثيقة USHAŞ أو HİB حصراً — بدونها الرفض مضمون', 'تأشيرة سائقي الشاحنات هي الوحيدة سنوية متعدّدة الدخول — الأنواع الأخرى دخول محدود', 'وثيقة قبول الجامعة يجب أن تتضمّن رقم YÖK ID بصيغة XX-XXX-XX', 'تأشيرة البحّارة وحدها بلا قائمة وثائق موحّدة — تُحدَّد حالةً بحالة بحسب العقد البحري', 'لا تقدم ببيانات متناقضة (مثلاً حجز أسبوع وتقول زيارة شهرين).']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'syria-turkey-visa-types-2026';

-- turkey-medical-visa  ←  1 صفحة
UPDATE articles SET
    documents = ARRAY['جواز سفر صالح (غالباً يُشترط 6 أشهر على الأقل).', 'صورة بيومترية حديثة بخلفية بيضاء.', 'استمارة طلب التأشيرة (حسب القنصلية/المركز).', 'حجز طيران ذهاب/عودة (قد يكون حجزاً مبدئياً بحسب البلد).', 'حجز فندقي أو عنوان إقامة أثناء العلاج.', 'تقرير طبي يوضح الحالة والحاجة للعلاج في تركيا.', 'وثيقة USHAŞ أو HİB (جوهري)', 'مستندات مالية: كشف حساب/راتب/إثبات عمل أو سجل تجاري بحسب الحالة.', 'نسخ من صفحات الجواز الحالية والسابقة (خصوصاً إن وُجدت تأشيرات سابقة).', 'موافقة كاتب العدل للقاصرين المرافقين']::text[],
    steps = ARRAY['حدد بلد التقديم (حسب إقامتك القانونية) وحدد القناة الرسمية/المركز المعتمد للتقديم.', 'جهّز ملف الغرض الطبي: تقرير طبي + دعوة/خطة علاج + مواعيد/مدة تقديرية.', 'جهّز ملف السفر المساند: حجوزات متسقة + إثبات مالي منطقي + عنوان إقامة.', 'قدّم الطلب واحضر الموعد إن طُلب، ثم تابع حالة الطلب حتى صدور النتيجة.']::text[],
    tips = ARRAY['اجعل مدة الإقامة المقترحة منطقية ومطابقة للخطة الطبية.', 'تجنب أي تناقض بين تواريخ العلاج والحجوزات والأوراق المالية.', 'للقاصرين قد تُطلب موافقات موثقة من ولي الأمر حسب الحالة وبلد التقديم.', 'بدون وثيقة USHAŞ أو HİB الرفض مضمون']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'turkey-medical-visa';

-- turkey-visa-types-2026  ←  4 صفحة
UPDATE articles SET
    documents = ARRAY['جواز سفر ساري (6 أشهر على الأقل)', 'صور بيومترية', 'كشف حساب بنكي', 'حجز فندق أو دعوة', 'حجز طيران ذهاب وإياب', 'تأمين سفر', 'خطاب من جهة العمل/الجامعة']::text[],
    steps = ARRAY['حدد إذا كنت تحتاج فيزا أو معفي', 'للإلكترونية: قدّم عبر evisa.gov.tr', 'لتأشيرة السفارة: احجز موعد بالسفارة', 'جهّز كل الأوراق المطلوبة', 'ادفع الرسوم', 'انتظر النتيجة واستلم جوازك', 'أدخل بيانات الجواز بدقة مطابقة للآلة المقروءة (MRZ) إن أمكن.']::text[],
    tips = ARRAY['قدّم مبكراً خصوصاً بالصيف — المواعيد بتنفد', 'تأكد من صلاحية جوازك 6 أشهر على الأقل', 'التأشيرة الإلكترونية أسرع وأسهل لو متاحة لجنسيتك', 'جهّز كشف بنكي مقنع — أهم وثيقة', 'إذا كنت تقدّم من بلد ليس بلد جنسيتك، ستحتاج إثبات إقامة قانونية في بلد التقديم.', 'أي خطأ في رقم الجواز/الاسم قد يجعل التأشيرة غير صالحة عملياً.', 'لا تخلط بين “إعفاء” و”e-Visa”: كلاهما يختلف حسب الجنسية.']::text[],
    last_update = CURRENT_DATE
WHERE slug = 'turkey-visa-types-2026';

-- تصحيح الإسناد ---------------------------------------------------------
UPDATE articles SET source = 'الأرقام بالدولار في هذه الصفحة مصدرها إعلان اتحاد منظمات المجتمع المدني للتنمية (UCSO) على صفحته على فيسبوك — وهو اتحاد أهلي، لا جهة حكومية تركية، ولم نجد الأرقام منشورةً على أي موقع رسمي تركي. أمّا الرسم القانوني التركي فتنشره رئاسة إدارة الهجرة (goc.gov.tr) نافذاً من 1 كانون الثاني 2026 بموجب الجريدة الرسمية 31 كانون الأول 2025 العدد 33124. والجهة المذكورة للتقديم في سوريا: Visa FG — sy.visafg.com/ar.', last_update = CURRENT_DATE
WHERE slug = 'syria-turkey-visa-types-2026';

-- تنبيه الرسوم، وربط العمودين ببعضهما -----------------------------------
UPDATE articles SET details = coalesce(details, '') || '<div style="margin-top:1.25rem;padding:1rem;border-radius:0.75rem;border:1px solid #fcd34d;background:#fffbeb;"><p style="margin:0 0 .5rem 0;"><strong>عن الأرقام بالدولار في هذه الصفحة:</strong> مصدرها إعلان اتحاد منظمات المجتمع المدني للتنمية (UCSO) — وهو اتحاد أهلي لا جهة حكومية تركية. لم نعثر على هذه الأرقام منشورةً على أي موقع رسمي تركي، فلا نستطيع تأكيدها.</p><p style="margin:0 0 .5rem 0;">والرسم القانوني الذي تنشره رئاسة إدارة الهجرة التركية للتأشيرة، نافذاً من 1 كانون الثاني 2026 (الجريدة الرسمية 31 كانون الأول 2025، العدد 33124): <strong>9,376.40 ليرة</strong> لتأشيرة الدخول بمرّة واحدة أو تأشيرة العبور، و<strong>31,410.00 ليرة</strong> لمتعدّدة الدخول. وهو رقم مختلف عمّا يذكره إعلان الاتحاد.</p><p style="margin:0;">الاحتمال الأرجح أنّ الفرق يعود إلى ما يتقاضاه المكتب المعتمد داخل سوريا لا إلى الرسم القانوني نفسه — لكنّه احتمال لا تأكيد. <strong>أكّد المبلغ في المكتب قبل الدفع</strong>، وراجع <a href="/article/turkey-visa-types-2026" style="color:#b45309;font-weight:bold;">جدول الرسوم القانونية بالليرة ومَن يُعفى منها</a>.</p></div>', last_update = CURRENT_DATE
WHERE slug = 'syria-turkey-visa-types-2026' AND coalesce(details, '') NOT LIKE '%/article/turkey-visa-types-2026%';

UPDATE articles SET details = coalesce(details, '') || '<div style="margin-top:1.25rem;padding:1rem;border-radius:0.75rem;border:1px solid #a7f3d0;background:#ecfdf5;"><p style="margin:0;"><strong>سوري وتقدّم من داخل سوريا؟</strong> الأنواع السبعة المفتوحة أمامك — العبور والاجتماعات والتجارية والدراسة والعلاج والنقل البري والبحّارة — ووثائق كلّ نوع، والمكتب المعتمد للتقديم، في <a href="/article/syria-turkey-visa-types-2026" style="color:#047857;font-weight:bold;">دليل التأشيرات التركية للسوريين ←</a></p></div>', last_update = CURRENT_DATE
WHERE slug = 'turkey-visa-types-2026' AND coalesce(details, '') NOT LIKE '%/article/syria-turkey-visa-types-2026%';

-- الصفحات المدموجة تُحذف بعد نقل ما يستحقّ
DELETE FROM articles WHERE slug IN ('turkey-transit-visa-syrians-2026', 'turkey-business-visa-syrians-2026', 'turkey-meeting-conference-visa-syrians-2026', 'turkey-sailor-visa-syrians-2026', 'turkey-truck-driver-visa-syrians-2026', 'turkey-visa-from-syria', 'turkey-treatment-visa-syrians-2026', 'turkey-visa-overview', 'turkey-evisa-guide', 'turkey-visa-europe-foreigners', 'turkey-visa-arab-countries');

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق — الأول 3 صفوف، والثاني صفر، والثالث صفّان كلاهما true
SELECT slug, coalesce(array_length(documents,1),0) AS docs,
       coalesce(array_length(steps,1),0) AS steps,
       coalesce(array_length(tips,1),0)  AS tips, last_update
FROM articles WHERE slug IN ('syria-turkey-visa-types-2026', 'turkey-medical-visa', 'turkey-visa-types-2026') ORDER BY slug;

SELECT slug FROM articles WHERE slug IN ('turkey-transit-visa-syrians-2026', 'turkey-business-visa-syrians-2026', 'turkey-meeting-conference-visa-syrians-2026', 'turkey-sailor-visa-syrians-2026', 'turkey-truck-driver-visa-syrians-2026', 'turkey-visa-from-syria', 'turkey-treatment-visa-syrians-2026', 'turkey-visa-overview', 'turkey-evisa-guide', 'turkey-visa-europe-foreigners', 'turkey-visa-arab-countries');

SELECT slug,
       (source NOT LIKE '%منشور رسمي بقلم%')                AS إسناد_مصحَّح,
       (details LIKE '%/article/turkey-visa-types-2026%'
        OR details LIKE '%/article/syria-turkey-visa-types-2026%') AS العمودان_مترابطان
FROM articles WHERE slug IN ('syria-turkey-visa-types-2026', 'turkey-visa-types-2026') ORDER BY slug;
